#!/usr/bin/env python3

import json

class ShellReporter:
    def report_categories(self, categories):
        to_dict = lambda x: { '{#TOOL}}': '{:s}'.format(x.tool), '{#TYPE}': '{:s}'.format(x.context) }
        category_dict_list = list(map(to_dict, categories))
        print(json.dumps(category_dict_list))

    def report_job(self, job):
        category = '{:s}-{:s}'.format(job.tool, job.type)
        self._report_job(job.timestamp, '{:s}-{:s}.STATUS'.format(job.tool, job.type), '{:d} ({:s})'.format(job.status, 'SUCCESS' if job.status else 'FAILURE'))
        self._report_job(job.timestamp, '{:s}-{:s}.DURATION'.format(job.tool, job.type), job.duration)

    def _report_job(self, timestamp, metric_name, metric_value):
        print('timestamp: {:%Y:%m:%dT:%H:%M:%S:%z} - metric_name: {:s} - metric_value: {}'.format(timestamp, metric_name, metric_value))

#!/usr/bin/env python3

from whale import CASE_CONVERT


class ShellReporter:
    def format_title(self, string):
        return CASE_CONVERT(string)

    def report_categories(self, categories):
        to_dict = lambda x: { self.format_title(x.tool): self.format_title(x.context) }
        category_dict_list = list(map(to_dict, categories))
        print(json.dumps(category_dict_list))

    def report_job(self, job):
        category = '{:s}-{:s}'.format(job.tool, job.type)
        self._report_job(job.timestamp, self.format_title(category + '.STATUS'), '{:d} ({:s})'.format(job.status, 'SUCCESS' if job.status else 'FAILURE'))
        self._report_job(job.timestamp, self.format_title(category + '.DURATION'), job.duration)

    def _report_job(self, timestamp, metric_name, metric_value):
        print('timestamp: {:%Y:%m:%dT:%H:%M:%S:%z} - metric_name: {:s} - metric_value: {}'.format(timestamp, metric_name, metric_value))

