from django.conf import settings
from django.contrib.auth.models import User as DjangoUser
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we get here, we need to check if there's a vanilla Django user
		# that matches our criteria...
		try:
			django_user = DjangoUser.objects.get(username=username)
			if django_user.is_active and django_user.check_password(password):
				# If we get here, we need to create a new custom User based on
				# the vanilla Django one, clone all the important bits over, then
				# delete the vanilla one and return the new custom one.
				custom_user = self.user_class()
				custom_user.username = django_user.username
				custom_user.first_name = django_user.first_name
				custom_user.last_name = django_user.last_name
				custom_user.email = django_user.email
				custom_user.is_staff = django_user.is_staff
				custom_user.is_active = django_user.is_active
				custom_user.is_superuser = django_user.is_superuser
				custom_user.set_password(django_user.password)

				custom_user.save()
				django_user.delete()
				return custom_user
		except DjangoUser.DoesNotExist:
			pass

		return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

